async def call_bank_refund(
    payment_id: str,
    amount: int,
    processor_id: str | None = None,       # Stripe PaymentIntent ID
    merchant_id: str | None = None,
    reason: str | None = None,
    idempotency_key: str | None = None,
) -> dict:
    """
    POST /refund → bank_connector → stripe.Refund.create()
    """
    payload = {
        "payment_id":      payment_id,
        "merchant_id":     merchant_id or "unknown",
        "processor_id":    processor_id,
        "amount":          amount,
        "reason":          reason,
        "idempotency_key": idempotency_key,
    }

    try:
        async with httpx.AsyncClient(timeout=TIMEOUT) as client:
            resp = await client.post(f"{BANK_CONNECTOR_URL}/refund", json=payload)
        resp.raise_for_status()
        data = resp.json()

        return {
            "success":          data.get("success", False),
            "refund_reference": data.get("refund_reference"),
            "message":          data.get("failure_message"),
        }

    except Exception as e:
        logger.exception(f"Bank connector error: refund payment={payment_id} error={e}")
        return {"success": False, "message": str(e)}
